*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_queryId;
scwin.vScrenID = "ULDSTF20300.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    chb_Grp_All.setValue(1);
    scwin.fn_allCheck();
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep_1.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep_1.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep_1.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp_1.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp_1.Reset();
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_ElwInst.Reset();

    // ETF 운용사 리스트(콤보)
    dts_TrstComList.DataID = "/CodeAction.do?method=listTrstComExists&For=R";
    dts_TrstComList.Reset();

    // PF 운용사 리스트(콤보)
    scwin.fn_TrstComList_PF();
    dts_Elwall.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_Elwall.Reset();
    rdo_ELW_ISUR_CD.setValue("1");
    dts_ElwUly.DataID = "/CodeAction.do?method=listElwUlyCd&For=R";
    dts_ElwUly.Reset();
    edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);

    //------ ETN START
    //발행회사 조회
    dts_EtnInst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_EtnInst.Reset();

    //종목조회
    scwin.fn_GetJongmok("", "Y");

    //기타설정
    edt_SDate_1.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_EDate_1.setValue($c.ut.cGetToday("yyyymmdd"));
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_1);

    //기초지수
    var urlBas = "/listingCommon.do";
    urlBas += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    urlBas += "&method=listGeneral" + "&outputMessageId=ETN_LSTISUDTLSRCH_OUT_COMBO" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstsrch.basIdxCd.list";
    dst_BAS_IDX_CD.DataID = encodeURI(urlBas);
    dst_BAS_IDX_CD.reset();
    strCbd = "^전체";
    /*for (j = 1; j <= dst_BAS_IDX_CD.CountRow; j++) { 값사이즈 초과
    	strCbd +=  (strCbd == "" ? "" : ",") + dst_BAS_IDX_CD.NameValue(j, "VALUE") + "^" + dst_BAS_IDX_CD.NameValue(j, "TEXT");
    }*/
    cmb_BAS_IDX_CD.CBData = strCbd;

    //상품유형, 수익구조 유형, 산출기관
    var arrCid = [{
        cid: "ETP_PROD_TP_CD",
        cnm: "cmb_ETP_PROD_TP_CD"
    }, {
        cid: "IDX_CALC_INST_CD",
        cnm: "cmb_IDX_CALC_INST_CD"
    }, {
        cid: "LOSS_LMT_ETN_EARNG_STRUCT_CD",
        cnm: "cmb_EARNG_STRUCT_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='ETP_PROD_TP_CD','IDX_CALC_INST_CD','LOSS_LMT_ETN_EARNG_STRUCT_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                if (dts_Cod.getCellData(j, "CD_ENG_NM") == "ETP_PROD_TP_CD" && dts_Cod.getCellData(j, "TEXT").indexOf("ETN") == -1) {
                    //상품유형은 ETN과 손실제한ETN만 표시
                    continue;
                } else {
                    strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                }
            }
        }
        objCod.CBData = strCbd;
    }
    //초기 Diable
    cmb_EARNG_STRUCT_TP_CD.setDisabled(true);
    cmb_EARY_REDMPT_COND_YN.setDisabled(true);
    //------ ETN END


    //------ 디지털증권 START
    //기간 
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_DGSE_SDate.setValue(vCurDate);
    edt_DGSE_EDate.setValue(vCurDate);

    //기간콤보박스
    var usrCBData = "1주일전^1,1개월전^2,3개월전^3,6개월전^4,1년전^5,2년전^6";
    cmb_DGSE_PeriodTp.CBData = usrCBData; //사용자CBData 지정

    //------ 디지털증권 END

};




/**
 * PF 운용사 목록 조회
 */
scwin.fn_TrstComList_PF = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.trstcom.pf.exists.select.list"; // 운용사
    dts_TrstComListPF.DataID = encodeURI(url);
    dts_TrstComListPF.reset();

    //GauceDataRow gauceDataRow = dts_TrstComListPF.newDataRow();
    //gauceDataRow.addColumnValue(""); // header 의 역할.
    //gauceDataRow.addColumnValue("전체"); // header 의 역할.
    //dts_TrstComListPF.addDataRow(gauceDataRow);

};








/**
 * ETN 발행회사에 대한 종목목록 조회
 */
scwin.fn_GetJongmok = function(isurcd, liststatcd) {
    //종목조회
    var etnurl = "/etn/EtnCodeAct.do?method=listIsuCdByStat&For=R";
    etnurl += "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT";
    etnurl += "&For=R";
    etnurl += "&V_ISUR_CD=" + isurcd;
    etnurl += "&V_LIST_STAT_CD=" + liststatcd;
    dts_EtnJongmok.DataID = etnurl;
    dts_EtnJongmok.Reset();
};


//조회
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var secuGrpId = "";
        if ($c.stf.getObjectValue(chb_Grp_St) == 'Y') secuGrpId += 'ST,';
        if ($c.stf.getObjectValue(chb_Grp_Mf) == 'Y') secuGrpId += 'MF,';
        if ($c.stf.getObjectValue(chb_Grp_Rt) == 'Y') secuGrpId += 'RT,';
        if ($c.stf.getObjectValue(chb_Grp_Sc) == 'Y') secuGrpId += 'SC,';
        if ($c.stf.getObjectValue(chb_Grp_Fs) == 'Y') secuGrpId += 'FS,';
        if ($c.stf.getObjectValue(chb_Grp_Dr) == 'Y') secuGrpId += 'DR,';
        if ($c.stf.getObjectValue(chb_Grp_If) == 'Y') secuGrpId += 'IF,';
        if ($c.stf.getObjectValue(chb_Grp_All) == ' Y') secuGrpId = '';
        var vMarketTpCd = js_market;

        //2020-02-14 etn, elw 조직개편 by nhkw
        if (panel_mkt_gubun_1.style.display == "") {
            vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD_1);
        }
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LIST_ISU_SEARCH_STOCK" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.isu.stock.condition" + "&{P}param01=" + vMarketTpCd + // 시장구분
            "&{P}param02=" + vMarketTpCd + // 시장구분
            "&{P}param03=" + secuGrpId + // 회사구분
            "&{P}param04=" + secuGrpId + // 회사구분
            "&{P}param05=" + $c.stf.getObjectValue(txb_ISUR_CD_1) + "&{P}param06=" + $c.stf.getObjectValue(txb_ISUR_CD_1) + "&{P}param07=" + $c.stf.getObjectValue(cmb_TeamList_1) + // 팀
            "&{P}param08=" + $c.stf.getObjectValue(cmb_TeamList_1) + // 팀
            "&{P}param09=" + $c.stf.getObjectValue(cmb_EmpList_1) + // 사원
            "&{P}param10=" + $c.stf.getObjectValue(cmb_EmpList_1) + // 사원
            "&{P}param11=" + $c.stf.getObjectValue(cmb_STKCERT_KIND_CD) + "&{P}param12=" + $c.stf.getObjectText(cmb_STKCERT_KIND_CD).substr(0, 2) + "&{P}param13=" + $c.stf.getObjectValue(cmb_PARVAL) + "&{P}param14=" + $c.stf.getObjectValue(cmb_PARVAL) + "&{P}param15=" + $c.stf.getObjectValue(rdo_HALT_YN_1) + "&{P}param16=" + $c.stf.getObjectValue(rdo_HALT_YN_1);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var vMarketTpCd = "";
        if (js_market == "1" || js_market == "2" || js_market == "6") {
            vMarketTpCd = js_market;
        } else {
            vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD_2);
        }
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LIST_ISU_SEARCH_ETF" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.isu.etf.condition" + "&{P}param01=" + vMarketTpCd + // 시장구분
            "&{P}param02=" + vMarketTpCd + // 시장구분
            "&{P}param03=" + $c.stf.getObjectValue(txb_ISU_CD_2) + "&{P}param04=" + $c.stf.getObjectValue(txb_ISU_CD_2) + "&{P}param05=" + $c.stf.getObjectValue(rdo_HALT_YN_2) + "&{P}param06=" + $c.stf.getObjectValue(rdo_HALT_YN_2) + "&{P}param07=" + $c.stf.getObjectValue(cmb_TrstCom) + // 운용사
            "&{P}param08=" + $c.stf.getObjectValue(cmb_TrstCom); // 운용사
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.reset();
        $c.cm.ShowWin(grd_List_2);
        // PF jackal_25.05.09

    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        var vMarketTpCd = "";
        if (js_market == "1" || js_market == "2" || js_market == "6") {
            vMarketTpCd = js_market;
        } else {
            vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD_8);
        }
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LIST_ISU_SEARCH_PF" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.isu.pf.condition" + "&{P}param01=" + vMarketTpCd + // 시장구분
            "&{P}param02=" + vMarketTpCd + // 시장구분
            "&{P}param03=" + $c.stf.getObjectValue(txb_ISU_CD_8) + "&{P}param04=" + $c.stf.getObjectValue(txb_ISU_CD_8) + "&{P}param05=" + $c.stf.getObjectValue(rdo_HALT_YN_8) + "&{P}param06=" + $c.stf.getObjectValue(rdo_HALT_YN_8) + "&{P}param07=" + $c.stf.getObjectValue(cmb_TrstComPF) + // 운용사
            "&{P}param08=" + $c.stf.getObjectValue(cmb_TrstComPF); // 운용사
        dts_List_8.DataID = encodeURI(url);
        dts_List_8.reset();
        $c.cm.ShowWin(grd_List_8);
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LIST_ISU_SEARCH_BC" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.isu.bc.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISU_CD_3) + "&{P}param02=" + $c.stf.getObjectValue(txb_ISU_CD_3) + "&{P}param03=" + $c.stf.getObjectValue(txb_ISUR_CD_3) + "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD_3) + "&{P}param05=" + $c.stf.getObjectValue(rdo_HALT_YN_3) + "&{P}param06=" + $c.stf.getObjectValue(rdo_HALT_YN_3);
        dts_List_3.DataID = encodeURI(url);
        dts_List_3.reset();
        $c.cm.ShowWin(grd_List_3);
    } else if (MaxTab_01.getSelectedTabIndex() == 5) {
        var vMarketTpCd = js_market;

        //2020-02-14 etn, elw 조직개편 by nhkw
        if (panel_mkt_gubun_4.style.display == "") {
            vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD_4);
        }
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LIST_ISU_SEARCH_WRNT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.isu.wrnt.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISU_CD_4) + "&{P}param02=" + $c.stf.getObjectValue(txb_ISU_CD_4) + "&{P}param03=" + $c.stf.getObjectValue(rdo_HALT_YN_4) + "&{P}param04=" + $c.stf.getObjectValue(rdo_HALT_YN_4) + "&{P}param05=" + vMarketTpCd + "&{P}param06=" + vMarketTpCd + "&{P}param07=" + $c.stf.getObjectValue(rdo_SECUGRP_ID) + "&{P}param08=" + $c.stf.getObjectValue(rdo_SECUGRP_ID);
        dts_List_4.DataID = encodeURI(url);
        dts_List_4.reset();
        $c.cm.ShowWin(grd_List_4);
    } else if (MaxTab_01.getSelectedTabIndex() == 6) {
        if ($c.stf.getObjectValue(cmb_DateType) == '5') {
            if ($c.stf.getObjectValue(edt_SDate) != $c.stf.getObjectValue(edt_EDate)) {
                $c.win.alert("[특정일]로 검색시는 시작일과 종료일을 동일하게 한후 검색하세요.");
                return;
            }
        }
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LIST_ISU_SEARCH_ELW" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.isu.elw.condition" + "&{P}param01=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + "&{P}param02=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD) + "&{P}param03=" + $c.stf.getObjectValue(cmb_DateType) + //상장일
            "&{P}param04=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param05=" + $c.stf.getObjectValue(edt_EDate) + "&{P}param06=" + $c.stf.getObjectValue(cmb_DateType) + //상장폐지일
            "&{P}param07=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param08=" + $c.stf.getObjectValue(edt_EDate) + "&{P}param09=" + $c.stf.getObjectValue(cmb_DateType) + //최종거래일
            "&{P}param10=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param11=" + $c.stf.getObjectValue(edt_EDate) + "&{P}param12=" + $c.stf.getObjectValue(cmb_DateType) + //행사기간
            "&{P}param13=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param14=" + $c.stf.getObjectValue(edt_EDate) + "&{P}param15=" + $c.stf.getObjectValue(cmb_DateType) + //특정일자
            "&{P}param16=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param17=" + $c.stf.getObjectValue(edt_EDate) + "&{P}param18=" + $c.stf.getObjectValue(rdo_FNC_ULY_TP_CD) + "&{P}param19=" + $c.stf.getObjectValue(rdo_FNC_ULY_TP_CD) + "&{P}param20=" + $c.stf.getObjectValue(rdo_FNC_ULY_TP_CD) + "&{P}param21=" + $c.stf.getObjectValue(rdo_FNC_ULY_TP_CD) + "&{P}param22=" + $c.stf.getObjectValue(rdo_FNC_ULY_TP_CD) + "&{P}param23=" + $c.stf.getObjectValue(cmb_ELW_RGHT_TP_CD) + "&{P}param24=" + $c.stf.getObjectValue(cmb_ELW_RGHT_TP_CD) + "&{P}param25=" + $c.stf.getObjectValue(cmb_ELW_EXER_TP_CD) + "&{P}param26=" + $c.stf.getObjectValue(cmb_ELW_EXER_TP_CD) + "&{P}param27=" + $c.stf.getObjectValue(cmb_ELW_LST_SETL_METHD_CD) + "&{P}param28=" + $c.stf.getObjectValue(cmb_ELW_LST_SETL_METHD_CD) + "&{P}param29=" + $c.stf.getObjectValue(txb_ISU_NM_5) + "&{P}param30=" + $c.stf.getObjectValue(txb_ISU_NM_5) + "&{P}param31=" + $c.stf.getObjectValue(cmb_ELW_ISUR_CD) + "&{P}param32=" + $c.stf.getObjectValue(rdo_ELW_ISUR_CD) + "&{P}param33=" + $c.stf.getObjectValue(cmb_ELW_ISUR_CD) + "&{P}param34=" + $c.stf.getObjectValue(rdo_ELW_ISUR_CD) + "&{P}param35=" + $c.stf.getObjectValue(cmb_ELW_ISUR_CD) + "&{P}param36=" + $c.stf.getObjectValue(rdo_HALT_YN_5) + "&{P}param37=" + $c.stf.getObjectValue(rdo_HALT_YN_5) + "&{P}param38=" + $c.stf.getObjectValue(cmb_ELW_RGHT_TP_KIND_CD) + "&{P}param39=" + $c.stf.getObjectValue(cmb_ELW_RGHT_TP_KIND_CD);
        dts_List_5.DataID = encodeURI(url);
        dts_List_5.reset();
        $c.cm.ShowWin(grd_List_5);
    } else if (MaxTab_01.getSelectedTabIndex() == 7) {
        if ($c.stf.getObjectValue(cmb_DateType_1) == '5') {
            if ($c.stf.getObjectValue(edt_SDate) != $c.stf.getObjectValue(edt_EDate)) {
                $c.win.alert("[특정일]로 검색시는 시작일과 종료일을 동일하게 한후 검색하세요.");
                return;
