scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    var Rows;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        Rows = dts_List_1.getTotalRow();
        $c.stf.showObj(label_42, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        Rows = dts_List_2.getTotalRow();
        $c.stf.showObj(label_42, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        Rows = dts_List_8.getTotalRow();
        $c.stf.showObj(label_42, true);
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        Rows = dts_List_3.getTotalRow();
        $c.stf.showObj(label_42, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 5) {
        Rows = dts_List_4.getTotalRow();
        $c.stf.showObj(label_42, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 6) {
        Rows = dts_List_5.getTotalRow();
        $c.stf.showObj(label_42, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 7) {
        Rows = dts_List_6.getTotalRow();
        $c.stf.showObj(label_42, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 8) {
        Rows = dts_List_7.getTotalRow();
        $c.stf.showObj(label_42, false);
    }
    $c.stf.FillGridHeaderTotalCnt(Rows, panel_page);
    //fn_list_sync();

};
