scwin.gform_onload = function() {
    if (js_market == "1" || js_market == "2" || js_market == "6") {
        //2020-02-14 etn, elw 조직개편 by nhkw
        if (js_dep_cd == "2B40") {
            // ELW시장팀(2B30), ETN시장팀(2B40)
            $c.cm.setColumnProp(grd_List_2, "TR_MKT_NM", "Show", false);
            $c.stf.showObj(panel_mkt_gubun_1, true);
            $c.stf.showObj(panel_mkt_gubun_2, false);
            $c.stf.showObj(panel_mkt_gubun_8, false);
            $c.stf.showObj(panel_mkt_gubun_4, true);
        } else {
            // default 초기값
            $c.cm.setColumnProp(grd_List_1, "TR_MKT_NM", "Show", false);
            $c.cm.setColumnProp(grd_List_2, "TR_MKT_NM", "Show", false);
            $c.cm.setColumnProp(grd_List_8, "TR_MKT_NM", "Show", false);
            $c.cm.setColumnProp(grd_List_4, "TR_MKT_NM", "Show", false);
            $c.stf.showObj(panel_mkt_gubun_1, false);
            $c.stf.showObj(panel_mkt_gubun_2, false);
            $c.stf.showObj(panel_mkt_gubun_8, false);
            $c.stf.showObj(panel_mkt_gubun_4, false);
        }
    } else {
        $c.stf.showObj(panel_mkt_gubun_1, true);
        $c.stf.showObj(panel_mkt_gubun_2, true);
        $c.stf.showObj(panel_mkt_gubun_8, true);
        $c.stf.showObj(panel_mkt_gubun_4, true);
    }
    if (js_market == "2" || js_market == "6") {
        $c.cm.setColumnProp(grd_List_1, "ISU_ENG_SYMBL", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "ISU_ENG_SYMBL", "Show", false);
        $c.cm.setColumnProp(grd_List_8, "ISU_ENG_SYMBL", "Show", false);
    }
    if (js_market == "6") {
        $c.stf.showObj(panel_CO_TYP, false);
    }
    $c.cm.PanelToGroupBox(panel_Top_1);
    $c.cm.PanelToGroupBox(panel_Top_2);
    $c.cm.PanelToGroupBox(panel_Top_8);
    $c.cm.PanelToGroupBox(panel_Top_3);
    $c.cm.PanelToGroupBox(panel_Top_4);
    $c.cm.PanelToGroupBox(panel_Top_5);
    $c.cm.PanelToGroupBox(panel_Top_6);
    MaxTab_01.setSelectedTabIndex(1);
    scwin.fn_SetCode();
    scwin.fn_list_sync();

    //2020-02-14 etn, elw 조직개편 by nhkw
    if (js_dep_cd == "2B40") {
        // ELW시장팀(2B30), ETN시장팀(2B40)
        $c.cm.fn_com_isur_all(txb_ISUR_CD_1, txb_COM_NM_1);
    } else {
        $c.cm.fn_com_isur(txb_ISUR_CD_1, txb_COM_NM_1);
    }
};
